with open(path, 'r', encoding='utf-8') as f:
    content = f.read()

def extract_grid(section):
    lines = [l.replace('\\n', '\n').strip() for l in section.split('\\n')]
    grid = []
    for i, line in enumerate(lines):
        parts = line.split()
        if len(parts) == 29:
            try:
                grid.append([int(x) for x in parts])
            except:
                pass
    return grid

idx_test = content.find('Test input')
test_grid = extract_grid(content[idx_test:])[:28]

# Find all rows with [8, 9, 9] pattern at EACH position
# Store as: row -> set of starting columns
rows_with_pattern = {}
for r in range(28):
    pattern_cols = set()
    row = test_grid[r]
    for c in range(len(row)-2):
        if row[c] == 8 and row[c+1] == 9 and row[c+2] == 9:
            pattern_cols.add(c)
    if pattern_cols:
        rows_with_pattern[r] = pattern_cols

print("Rows with [8,9,9] pattern:")
for r in sorted(rows_with_pattern.keys()):
    print(f"  Row {r}: cols {sorted(rows_with_pattern[r])}")

# Find longest consecutive runs
consecutive_runs = []
run_start = None
for r in sorted(rows_with_pattern.keys()):
    if run_start is None or r != run_start + (len(consecutive_runs)):
        # Check if this continues previous run
        if run_start is not None and r == run_start + 1:
            run_end = r
            if len(consecutive_runs) >= 2:  # Need at least 3 rows
                consecutive_runs.append((run_start, r))
                run_start = None
            else:
                run_start = r
        else:
            run_start = r
    else:
        continue

# Simpler: find runs where every row from start to end has at least one match
print("\nFinding consecutive runs (3+ rows):")
runs = []
if rows_with_pattern:
    sorted_rows = sorted(rows_with_pattern.keys())
    current_run = [sorted_rows[0]]
    for r in sorted_rows[1:]:
        if r == current_run[-1] + 1:
            current_run.append(r)
        else:
            if len(current_run) >= 3:
                runs.append(current_run)
            current_run = [r]
    if len(current_run) >= 3:
